import { OrderStatus } from "../../domain/order";
import { PaymentStatus } from "../../domain/payment";
import { ShipmentStatus } from "../../domain/shipment";
import { ORDER_BADGES } from "./orderBadges";
import { PAYMENT_BADGES } from "./paymentBadges";
import { SHIPMENT_BADGES } from "./shipmentBadges";
import { Badge } from "./types";

export { Badge, Tone } from "./types";

// Each status family has its own vocabulary: "PENDING" means one thing for an
// order and another for a payment, so lookups must stay per-family.
const UNKNOWN_TONE = "neutral" as const;

function copyOf(badge: Badge | undefined, fallbackLabel: string): Badge {
  return badge ? { ...badge } : { label: fallbackLabel, tone: UNKNOWN_TONE };
}

export function orderBadge(status: OrderStatus | string): Badge {
  return copyOf(ORDER_BADGES[status as OrderStatus], status);
}

export function paymentBadge(status: PaymentStatus | string): Badge {
  return copyOf(PAYMENT_BADGES[status as PaymentStatus], status);
}

export function shipmentBadge(status: ShipmentStatus | string): Badge {
  return copyOf(SHIPMENT_BADGES[status as ShipmentStatus], status);
}

